mapper.update:
UPDATE sr_dag_node_attempt
SET status = 40,
    result_json = CAST(#{resultJson} AS JSONB),
    result_ref = #{resultRef},
    finished_at = #{now},
    version = version + 1,
    updated_at = #{now}
WHERE id = #{attemptId}
  AND status IN (10, 30, 80)
  AND attempt_lease_version = #{leaseVersion}

UPDATE sr_dag_node_attempt
SET status = 50,
    error_code = #{errorCode},
    error_message = #{errorMessage},
    finished_at = #{now},
    version = version + 1,
    updated_at = #{now}
WHERE id = #{attemptId}
  AND status IN (10, 30, 80)
  AND attempt_lease_version = #{leaseVersion}

UPDATE sr_dag_node_attempt
SET status = 80,
    finished_at = COALESCE(finished_at, #{now}),
    version = version + 1,
    updated_at = #{now}
WHERE id = #{attemptId}
  AND status = 10
  AND execution_deadline_at IS NOT NULL
  AND execution_deadline_at > #{now}

UPDATE sr_dag_node_attempt
SET attempt_lease_expire_time = #{newLeaseExpireTime},
    status = CASE
        WHEN status IN (10, 80) THEN 30
        ELSE status
    END,
    started_at = COALESCE(started_at, #{now}),
    version = version + 1,
    updated_at = #{now}
WHERE id = #{attemptId}
  AND attempt_lease_version = #{leaseVersion}
  AND worker_id = #{workerId}
  AND worker_epoch = #{workerEpoch}
  AND status IN (10, 30, 80)

UPDATE sr_dag_node_attempt
SET attempt_lease_version = #{newLeaseVersion},
    worker_epoch = #{newWorkerEpoch},
    attempt_lease_expire_time = #{newLeaseExpireTime},
    version = version + 1,
    updated_at = #{now}
WHERE id = #{attemptId}
  AND attempt_lease_version = #{currentLeaseVersion}
  AND status IN (10, 30, 80)
